<template>
    <div class="session-header">
        <div class="session-info">
            <div class="session-chat-title">{{ session.title }}</div>
            <div class="session-meta-part">
                <span v-if="formattedTime" class="session-time">
                    {{ `${t('startedOn', {date: formattedTime})}` }}
                </span>
                <span v-if="session.remark && formattedTime" class="separator">|</span>
                <span v-if="session.remark" class="session-remark">
                    {{ t('remark') }}: {{ session.remark }}
                </span>
            </div>
        </div>
        <div class="session-actions">
            <div class="action-btn" @click="handleShare" :title="t('share')">
                <l-img src="/static/icon_share.png" w='25px' h='25px' />
            </div>
            <div class="action-btn" @click="handleShowDetails" :title="t('prompt')">
                <l-img src="/static/images/image_chat/prompt_icon.png" w='18px' h='18px' />
            </div>
        </div>
    </div>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';

const { t } = useI18n();

// Props 定义
const props = defineProps({
    session: {
        type: Object,
        required: true
    },
    character: {
        type: Object,
        required: true
    },
    formatDateOnly: {
        type: Function,
        required: true
    }
});

// Emits 定义
const emit = defineEmits([
    'share',
    'show-details'
]);

// 计算属性
const formattedTime = computed(() => {
    if (props.session && props.session.last_message_time) {
        return props.formatDateOnly(props.session.last_message_time);
    }
    return '';
});

// 事件处理函数
const handleShare = () => {
    emit('share', props.session);
};

const handleShowDetails = () => {
    emit('show-details', props.character);
};
</script>

